using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The MCP SDK instantiates tool classes via DI.
    // Any constructor parameter registered in the DI container is injected automatically.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a US city by latitude and longitude.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        // Resolve grid coordinates from the NWS API
        var pointUrl = $"https://api.weather.gov/points/{latitude},{longitude}";
        var point = await _httpClient.GetFromJsonAsync<PointResponse>(pointUrl, cancellationToken);

        if (point?.Properties?.ForecastUrl is null)
            return "Could not resolve forecast location. Ensure coordinates are within the US.";

        var forecast = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            point.Properties.ForecastUrl, cancellationToken);

        if (forecast?.Properties?.Periods is not { Count: > 0 })
            return "No forecast data available.";

        var lines = forecast.Properties.Periods
            .Take(3)
            .Select(p => $"{p.Name}: {p.Temperature}°{p.TemperatureUnit} – {p.ShortForecast}");

        return string.Join("\n", lines);
    }

    [McpServerTool, Description("Get active weather alerts for a US state (two-letter code, e.g. 'CA').")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code")] string state,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.weather.gov/alerts/active?area={state}";
        var response = await _httpClient.GetFromJsonAsync<AlertResponse>(url, cancellationToken);

        if (response?.Features is not { Count: > 0 })
            return $"No active alerts for {state}.";

        var lines = response.Features
            .Take(5)
            .Select(f => $"[{f.Properties.Severity}] {f.Properties.Event}: {f.Properties.Headline}");

        return string.Join("\n\n", lines);
    }
}

// --- JSON models for the NWS API ---

public record PointResponse
{
    [JsonPropertyName("properties")]
    public PointProperties? Properties { get; init; }
}

public record PointProperties
{
    [JsonPropertyName("forecast")]
    public string? ForecastUrl { get; init; }
}

public record ForecastResponse
{
    [JsonPropertyName("properties")]
    public ForecastProperties? Properties { get; init; }
}

public record ForecastProperties
{
    [JsonPropertyName("periods")]
    public List<ForecastPeriod>? Periods { get; init; }
}

public record ForecastPeriod
{
    [JsonPropertyName("name")]
    public string Name { get; init; } = "";
    [JsonPropertyName("temperature")]
    public int Temperature { get; init; }
    [JsonPropertyName("temperatureUnit")]
    public string TemperatureUnit { get; init; } = "";
    [JsonPropertyName("shortForecast")]
    public string ShortForecast { get; init; } = "";
}

public record AlertResponse
{
    [JsonPropertyName("features")]
    public List<AlertFeature>? Features { get; init; }
}

public record AlertFeature
{
    [JsonPropertyName("properties")]
    public AlertProperties Properties { get; init; } = new();
}

public record AlertProperties
{
    [JsonPropertyName("event")]
    public string Event { get; init; } = "";
    [JsonPropertyName("severity")]
    public string Severity { get; init; } = "";
    [JsonPropertyName("headline")]
    public string Headline { get; init; } = "";
}

